// Same as the description in the prompt, implemented as a Verilog module.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] count2;
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'd0;
            delay <= 4'd0;
            count2 <= 16'd0;
            state <= 2'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                2'd0: begin // Waiting for 1101.
                    if (data & ~delay[0]) state <= 2'd1;
                    else if (~data) state <= 2'd0;
                end
                2'd1: begin // Waiting for 1101.
                    if (data & ~delay[0]) state <= 2'd1;
                    else if (~data) begin
                        state <= 2'd2;
                        counting <= 1'b1;
                    end
                end
                2'd2: begin // Counting.
                    if (count2 == 16'd999) begin
                        count2 <= 16'd0;
                        count <= count + 4'd1;
                    end else count2 <= count2 + 16'd1;
                    if (count == delay) begin
                        counting <= 1'b0;
                        done <= 1'b1;
                        state <= 2'd3;
                    end
                end
                2'd3: begin // Waiting for ack.
                    if (ack) begin
                        count <= 4'd0;
                        delay <= 4'd0;
                        count2 <= 16'd0;
                        state <= 2'd0;
                        done <= 1'b0;
                    end
                end
            endcase
            delay <= {delay[2:0], data};
        end
    end
endmodule

