// Same as the reference, but the delay counter is implemented using an
// always @(posedge clk) block and a counter inside it, rather than a
// generate-begin-end block nested inside the always. This makes the
// circuit smaller and the synthesis result easier to read.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] delay_counter;
    reg [15:0] count_counter;
    reg [3:0] state;
    reg [3:0] next_state;
    wire pattern = (state == 4);
    wire count_done = (count_counter == {delay, 10'b0} + 10'b1);
    wire next_counting = (state == 1);
    wire next_done = (state == 5);
    wire next_count = (count_done ? 4'b0000 : count + 1);
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            delay <= 0;
            delay_counter <= 0;
            count_counter <= 0;
            counting <= 0;
            done <= 0;
            count <= 4'b0000;
        end else begin
            state <= next_state;
            delay <= (state == 1) ? delay : (pattern ? data : delay);
            delay_counter <= (state == 1) ? delay_counter + 1 : 0;
            count_counter <= (state == 1) ? count_counter + 1 : 0;
            counting <= next_counting;
            done <= next_done;
            count <= next_count;
        end
    end
    always @(*) begin
        case (state)
            0: if (data) next_state = 1; else next_state = 0;
            1: if (delay_counter == 1000) next_state = 2; else next_state = 1;
            2: if (delay_counter == 2000) next_state = 3; else next_state = 2;
            3: if (delay_counter == 3000) next_state = 4; else next_state = 3;
            4: if (delay_counter == 4000) next_state = 5; else next_state = 4;
            5: if (ack) next_state = 0; else next_state = 5;
            default: next_state = 0;
        endcase
    end
endmodule

