// One-shot pulse generator, used to go from the "counting" state to the
// "waiting for ack" state. Triggers as soon as the register matches the
// input, regardless of how many clock cycles have passed.
module one_shot (
    input clk, reset, trigger,
    output reg pulse
);
    reg latch;
    always @(posedge clk) begin
        if (reset) begin
            latch <= 0;
            pulse <= 0;
        end else begin
            latch <= trigger;
            pulse <= trigger & ~latch;
        end
    end
endmodule

