// Timer that starts counting on a specific input pattern, determines the
// duration to delay, waits for the counters to finish counting, and notifies
// the user after the delay has passed. The user must acknowledge the timer
// to restart the cycle.
module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] state;
    reg [1:0] stateNext;
    reg [3:0] countNext;
    reg countingNext;
    reg doneNext;
    reg [15:0] counterNext;
    reg [3:0] delayNext;
    reg [1:0] state;
    reg [1:0] stateNext;
    reg [3:0] count;
    reg [3:0] countNext;
    reg counting;
    reg countingNext;
    reg done;
    reg doneNext;
    reg [15:0] counter;
    reg [15:0] counterNext;
    reg [3:0] delay;
    reg [3:0] delayNext;
    always @(*) begin
        stateNext = state;
        countNext = count;
        countingNext = counting;
        doneNext = done;
        counterNext = counter;
        delayNext = delay;
        case (state)
            2'd0: begin // Search for the start sequence 1101
                if (data && !counting && !done) begin
                    stateNext = 2'd1;
                end
            end
            2'd1: begin // Shift in the next 4 bits to determine the delay
                delayNext = {data, delay[3:1]};
                stateNext = 2'd2;
            end
            2'd2: begin // Start counting and go back to the start state
                countingNext = 1;
                counterNext = 16'd0;
                stateNext = 2'd0;
                doneNext = 1;
            end
        endcase
        if (ack) doneNext = 0;
        if (reset) begin
            stateNext = 2'd0;
            countNext = 4'd0;
            countingNext = 1'd0;
            doneNext = 1'd0;
            counterNext = 16'd0;
            delayNext = 4'd0;
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'd0;
            count <= 4'd0;
            counting <= 1'd0;
            done <= 1'd0;
            counter <= 16'd0;
            delay <= 4'd0;
        end else begin
            state <= stateNext;
            count <= countNext;
            counting <= countingNext;
            done <= doneNext;
            counter <= counterNext;
            delay <= delayNext;
            if (counting) begin
                counterNext = counter + 1;
                if (counter == (delay + 1) * 1000 - 1) begin
                    countingNext = 0;
                    countNext = delay;
                end else begin
                    countNext = delay - counter / 1000;
                end
            end
        end
    end
endmodule

