// One-bit up-down counter, used to count the delay. The "load" input
// forces the counter to go to a fixed value (0), then counts up to
// the target value. Once the target value is reached, the counter
// goes back to 0 and stays at 0 until the "load" input goes high again.
module updowncounter (
  input clk, reset,
  input load,
  input up,
  input [3:0] target,
  output reg [3:0] count,
  output reg done
);
  always @(posedge clk) begin
    if (reset) count <= 4'd0;
    else begin
      if (load) count <= 4'd0;
      else if (count == target) begin
        count <= 4'd0;
        done <= 1;
      end else begin
        count <= up ? count + 4'd1 : count - 4'd1;
        done <= 0;
      end
    end
  end
endmodule

