// Timer with one input, delayed by a number of cycles determined by an
// additional input pulse, which must be counted exactly. The output
// remaining time is a down-counter, counting to zero and then going back
// to (delay-1) and counting down again, etc., up to delay cycles, then
// going to zero and the done signal is asserted.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] remaining;
    reg [15:0] total;
    reg [1:0] state;
    reg [1:0] nextstate;
    reg [1:0] startdelay;
    reg [1:0] delaycount;
    wire start = (state == 0) && (data & ~startdelay[0]) || (state == 1) && (data & ~startdelay[1]);
    wire start2 = (state == 0) && (~data & ~startdelay[0]) || (state == 1) && (~data & ~startdelay[1]);
    wire [15:0] target = (counting ? total - 1 : total);
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            startdelay <= 2'b11;
            count <= 4'd0;
            remaining <= 16'd1000;
            total <= 16'd1000;
            delay <= 4'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= nextstate;
            remaining <= remaining - 1;
            if (remaining == 0) begin
                count <= count + 1;
                remaining <= total;
            end
            if (start) begin
                delaycount <= 2'd0;
            end
            if (start2) begin
                delaycount <= 2'd1;
            end
            if (delaycount == 2'd1) begin
                delay <= data;
                total <= (delay + 1) * 1000;
                counting <= 1'b1;
            end
            if (count == 4'd10) begin
                counting <= 1'b0;
                done <= 1'b1;
            end
            if (ack) done <= 1'b0;
        end
    end
    always @(*) begin
        case (state)
            0: nextstate = data ? 1 : 0;
            1: nextstate = data ? 2 : 1;
            2: nextstate = data ? 2 : 3;
            3: nextstate = (~data & ~startdelay[2]) ? 4 : 3;
            4: nextstate = (~data & ~startdelay[3]) ? 0 : 4;
        endcase
        startdelay <= {data, startdelay[1:0]};
    end
endmodule

