    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg        counting,
    output reg        done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] state;
    reg [1:0] state_next;
    reg [3:0] count_next;
    reg counting_next;
    reg done_next;
    reg [15:0] counter_next;
    reg [3:0] delay_next;
    always @(*) begin
        state_next = state;
        count_next = count;
        counting_next = counting;
        done_next = done;
        counter_next = counter;
        delay_next = delay;
        case (state)
            0: begin // Search for the start sequence 1101
                if (data & ~counter[15]) counter_next = counter + 1;
                else if (~data & counter[15]) counter_next = 1;
                else if (counter[15:0] == 16'h2D01) state_next = 1;
                else counter_next = 0;
            end
            1: begin // Shift in the next 4 bits to determine the duration
                if (counter == 1) delay_next = {data, delay[3:1]};
                else if (counter < 1001) begin
                    counter_next = counter + 1;
                    count_next = (1000 - counter) / 1000;
                end
                else begin
                    state_next = 2;
                    counter_next = 1;
                end
            end
            2: begin // Count for exactly (delay + 1) * 1000 cycles
                if (counter < 1000) begin
                    counter_next = counter + 1;
                    count_next = delay;
                    if (counter == 999) done_next = 1;
                end
                else begin
                    state_next = 0;
                    counter_next = 0;
                    delay_next = 0;
                    count_next = 0;
                    done_next = 0;
                end
            end
        endcase
        if (reset) begin
            state_next = 0;
            counter_next = 0;
            delay_next = 0;
            count_next = 0;
            done_next = 0;
        end
        if (ack) done_next = 0;
    end
    always @(posedge clk) begin
        state <= state_next;
        counter <= counter_next;
        delay <= delay_next;
        count <= count_next;
        counting <= counting_next;
        done <= done_next;
        if (state == 2) counting_next = 1;
        else if (state == 0 & ack) counting_next = 0;
    end
