// One-shot: goes high once per input pulse, then goes back to low.
module one_shot (
    input  clk,
    input  reset,
    input  pulse,
    output reg pulse_once
);
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'd0;
            pulse_once <= 1'b0;
        end else begin
            case (state)
                2'd0: begin
                    pulse_once <= 1'b0;
                    if (pulse) state <= 2'd1;
                end
                2'd1: begin
                    pulse_once <= 1'b1;
                    state <= 2'd2;
                end
                2'd2: begin
                    pulse_once <= 1'b0;
                    if (!pulse) state <= 2'd0;
                end
            endcase
        end
    end
endmodule

