// The function 'counting_remaining' calculates the remaining time of the
// counting stage and returns the 4-bit counter value corresponding to this
// time.
function [3:0] counting_remaining (input [3:0] delay, input [15:0] counter);
    begin
        if (counter < 1000) return delay;
        else if (counter < 2000) return delay - 1;
        else if (counter < 3000) return delay - 2;
        else if (counter < 4000) return delay - 3;
        else if (counter < 5000) return delay - 4;
        else if (counter < 6000) return delay - 5;
        else if (counter < 7000) return delay - 6;
        else if (counter < 8000) return delay - 7;
        else if (counter < 9000) return delay - 8;
        else return delay - 9;
    end
endfunction

