    reg [15:0] count2;
    reg [1:0] state;
    reg [3:0] up;
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            delay <= 4'd0;
            count2 <= 16'd0;
            counting <= 1'b0;
            done <= 1'b0;
            count <= 4'd0;
        end else begin
            case (state)
                2'b00: begin // wait for 1101
                    if (data & ~delay[0] & delay[1] & ~delay[2] & delay[3]) begin
                        state <= 2'b01;
                        up <= 4'd0;
                        count2 <= 16'd0;
                        count <= 4'd0;
                        counting <= 1'b1;
