                        count2 <= count2 + 16'd1;
                    if (count2 == 16'd999)
                        count <= count + 1'b1;
                    if (up == delay) begin
                        state <= 2'b10;
                        done <= 1'b1;
                    end
                end
                2'b10: begin // wait for ack
                    if (ack) begin
                        state <= 2'b00;
                        done <= 1'b0;
                    end
                end
            endcase
        end
    end
